class Slide:
 def __init__(self,title,subtitle,source,notes,section='TECHNICAL PROGRESS REVIEW',takeaway=None):
  self.d=dict(id=f'S{len(slides)+1:02}',title=title,subtitle=subtitle,source=source,notes=notes,section=section,shapes=[]);slides.append(self.d)
  self.rect(0,0,1600,900,'#FAFCFA',None);self.rect(0,0,1600,12,GREEN,None)
  self.text(65,34,'STUDENT EXCHANGE  /  '+section,13,GREEN,True)
  title_size=37
  while stringWidth(title,'Review-Bold',title_size)>1470:title_size-=1
  self.text(65,75,title,title_size,INK,True);self.text(65,132,subtitle,19,GRAY)
  self.line([(65,824),(1535,824)],BORDER,1)
  self.text(65,844,source,12,GRAY);self.text(1535,844,self.d['id'],13,GRAY,True,'right')
  if takeaway:self.rect(65,758,1470,58,GOLD,None,5);self.wrap(82,771,takeaway,1434,18,23,INK,True)
 def add(self,type,**kw):self.d['shapes'].append(dict(type=type,**kw))
 def rect(self,x,y,w,h,fill=WHITE,stroke=BORDER,r=0,dash=False):self.add('rect',x=x,y=y,w=w,h=h,fill=fill,stroke=stroke,r=r,dash=dash)
 def line(self,points,color=BORDER,width=1.5,dash=False):self.add('line',points=points,color=color,width=width,dash=dash)
 def text(self,x,y,text,size=21,color=INK,bold=False,align='left',italic=False):self.add('text',x=x,y=y,text=text,size=size,color=color,bold=bold,align=align,italic=italic)
 def wrap(self,x,y,text,width,size=21,gap=30,color=INK,bold=False,align='left'):
  parts=[];line='';font='Review-Bold' if bold else 'Review'
  for word in text.split():
   candidate=(line+' '+word).strip()
   if stringWidth(candidate,font,size)>width and line:parts.append(line);line=word
   else:line=candidate
  if line:parts.append(line)
  for i,t in enumerate(parts):self.text(x,y+i*gap,t,size,color,bold,align)
  return len(parts)*gap
 def card(self,x,y,w,h,title,body,color=MINT):
  self.rect(x,y,w,h,color,None,7);th=self.wrap(x+22,y+19,title,w-44,25,32,INK,True)
  by=max(y+72,y+19+th+14);fs=21
  def lines_needed(text,width,size):
   n=1;ln=''
   for word in text.split():
    cand=(ln+' '+word).strip()
    if stringWidth(cand,'Review',size)>width and ln:n+=1;ln=word
    else:ln=cand
   return n
  while lines_needed(body,w-44,fs)*(fs*1.45)>y+h-by-15 and fs>16:fs-=.5
  self.wrap(x+22,by,body,w-44,fs,fs*1.45)
 def arrow(self,points,label='',at=None,dash=False,head='filled',color=GRAY,size=17):
  self.line(points,color,1.8,dash);a,b=points[-2:];ang=math.atan2(b[1]-a[1],b[0]-a[0]);u=(math.cos(ang),math.sin(ang));z=(-u[1],u[0]);p1=(b[0]-11*u[0]+5*z[0],b[1]-11*u[1]+5*z[1]);p2=(b[0]-11*u[0]-5*z[0],b[1]-11*u[1]-5*z[1])
  if head=='filled':self.add('polygon',points=[b,p1,p2],fill=color,stroke=color)
  elif head=='triangle':self.add('polygon',points=[b,p1,p2],fill=WHITE,stroke=color)
  elif head=='open':self.line([p1,b,p2],color)
  if label:
   if at is None:at=((a[0]+b[0])/2,(a[1]+b[1])/2-25)
   self.text(at[0],at[1],label,size,INK,False,'center')
 def box(self,x,y,w,h,title,body=(),color=BLUE,tag=None):
  self.rect(x,y,w,h,color,BORDER,5)
  yy=y+12
  if tag:self.text(x+w/2,yy,tag,14,GRAY,False,'center');yy+=26
  self.wrap(x+w/2,yy,title,w-28,22,27,INK,True,'center')
  for i,t in enumerate(body):self.text(x+17,yy+42+i*27,t,18)
 def cls(self,x,y,w,title,attributes,methods=(),color=BLUE):
  hh=43+len(attributes)*27+12+(len(methods)*27+13 if methods else 0)
  self.rect(x,y,w,hh,WHITE,BORDER);self.rect(x,y,w,43,color,BORDER);self.text(x+w/2,y+12,title,21,INK,True,'center')
  for i,t in enumerate(attributes):self.text(x+14,y+57+i*27,t,18)
  if methods:
   yy=y+43+len(attributes)*27+12;self.line([(x,yy),(x+w,yy)],BORDER)
   for i,t in enumerate(methods):self.text(x+14,yy+12+i*27,t,17)
  return hh
 def actor(self,x,y,label):
  self.add('ellipse',x=x-12,y=y,w=24,h=24,fill=WHITE,stroke=INK);self.line([(x,y+24),(x,y+67)],INK);self.line([(x-26,y+40),(x+26,y+40)],INK);self.line([(x-24,y+95),(x,y+67),(x+24,y+95)],INK);self.text(x,y+106,label,18,INK,True,'center')
 def oval(self,x,y,w,h,label,color=MINT):
  self.add('ellipse',x=x,y=y,w=w,h=h,fill=color,stroke=BORDER);ls=label.split('\n')
  for i,t in enumerate(ls):self.text(x+w/2,y+h/2-len(ls)*12+i*27,t,20,INK,False,'center')
 def table(self,headers,rows,widths,top=205,rowh=69,size=19):
  x0=65
  for i,row in enumerate([headers]+rows):
   y=top+i*rowh;x=x0
   for w,t in zip(widths,row):
    self.rect(x,y,w,rowh,NAVY if i==0 else (BLUE if i%2==0 else WHITE),WHITE)
    self.wrap(x+14,y+14,t,w-28,size if i else size,25,WHITE if i==0 else INK,i==0);x+=w
 def image(self,path,x,y,w,h,crop=None):
  iw,ih=Image.open(BASE/path).size
  if crop:iw*=1-crop[0]-crop[2];ih*=1-crop[1]-crop[3]
  scale=min(w/iw,h/ih);ww,hh=iw*scale,ih*scale
  self.add('image',path=path,x=x+(w-ww)/2,y=y+(h-hh)/2,w=ww,h=hh,crop=crop)

